class Solution {
public:
    int maxSideLength(vector<vector<int>>& mat, int threshold) {
        int m = mat.size();
        int n = mat[0].size();
        vector<vector<int>> pref(m + 1, vector<int>(n + 1, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                pref[i + 1][j + 1] = pref[i][j + 1] + pref[i + 1][j] - pref[i][j] + mat[i][j];

        int side = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                while (true) {
                    int k = side + 1;
                    if (k > i + 1 || k > j + 1) break;
                    int r2 = i + 1, c2 = j + 1;
                    int r1 = r2 - k, c1 = c2 - k;
                    int sum = pref[r2][c2] - pref[r1][c2] - pref[r2][c1] + pref[r1][c1];
                    if (sum > threshold) break;
                    side = k;
                }
            }
        }
        return side;
    }
};
